import { useNavigate } from 'react-router-dom';
import { ArrowRight, Trash2, Moon, Sun, Languages, Cpu, RotateCcw, ArrowLeft } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Card } from '@/components/ui/Card';
import { ProfileForm } from '@/components/profile/ProfileForm';
import { useSettingsStore } from '@/lib/store/settingsStore';
import { usePromptStore } from '@/lib/store/promptStore';
import { useWizardStore } from '@/lib/store/wizardStore';
import { useProfileStore } from '@/lib/store/profileStore';
import { useLanguage } from '@/components/layout/LanguageProvider';
import { useTheme } from '@/components/layout/ThemeProvider';

export default function SettingsPage() {
  const navigate = useNavigate();
  const { lang, setLang, t } = useLanguage();
  const { isDark } = useTheme();
  const { theme, setTheme } = useSettingsStore();
  const { history, clearHistory } = usePromptStore();
  const { reset: resetWizard } = useWizardStore();
  const { reset: resetProfile } = useProfileStore();
  const isLtr = document.documentElement.dir === 'ltr';

  const resetAll = () => {
    if (!confirm(t('settings.resetConfirm'))) return;
    resetWizard();
    resetProfile();
    clearHistory();
    localStorage.clear();
    navigate('/');
  };

  return (
    <div className="mx-auto max-w-3xl px-4 py-10 sm:px-6">
      <div className="mb-6 flex items-center gap-2">
        <Button variant="ghost" size="sm" onClick={() => navigate('/')}>
          {isLtr ? <ArrowLeft size={16} /> : <ArrowRight size={16} />} {t('common.back')}
        </Button>
        <h1 className="text-2xl font-bold text-gradient">{t('settings.title')}</h1>
      </div>

      <div className="space-y-4">
        {/* Profile */}
        <ProfileForm />

        {/* Theme */}
        <Card padding="lg">
          <h2 className="mb-3 flex items-center gap-2 text-lg font-bold text-text-primary">
            {isDark ? <Moon size={18} /> : <Sun size={18} />}
            {t('settings.appearance')}
          </h2>
          <div className="flex gap-2">
            <Button
              variant={theme === 'dark' ? 'primary' : 'secondary'}
              size="sm"
              onClick={() => setTheme('dark')}
            >
              <Moon size={14} /> {t('settings.dark')}
            </Button>
            <Button
              variant={theme === 'light' ? 'primary' : 'secondary'}
              size="sm"
              onClick={() => setTheme('light')}
            >
              <Sun size={14} /> {t('settings.light')}
            </Button>
          </div>
        </Card>

        {/* Language */}
        <Card padding="lg">
          <h2 className="mb-3 flex items-center gap-2 text-lg font-bold text-text-primary">
            <Languages size={18} /> {t('settings.language')}
          </h2>
          <div className="flex gap-2">
            <Button
              variant={lang === 'ar' ? 'primary' : 'secondary'}
              size="sm"
              onClick={() => setLang('ar')}
            >
              {t('settings.languages.ar')}
            </Button>
            <Button
              variant={lang === 'en' ? 'primary' : 'secondary'}
              size="sm"
              onClick={() => setLang('en')}
            >
              {t('settings.languages.en')}
            </Button>
          </div>
        </Card>

        {/* Data management */}
        <Card padding="lg">
          <h2 className="mb-3 flex items-center gap-2 text-lg font-bold text-text-primary">
            <Cpu size={18} /> {t('settings.data')}
          </h2>
          <div className="space-y-3">
            <div className="flex items-center justify-between rounded-lg border border-border bg-surface p-3">
              <div>
                <p className="text-sm font-bold text-text-primary">{t('history.title')}</p>
                <p className="text-xs text-text-muted">{t('settings.savedCount', { count: history.length })}</p>
              </div>
              <Button variant="secondary" size="sm" onClick={clearHistory} disabled={history.length === 0}>
                <Trash2 size={14} /> {t('settings.clear')}
              </Button>
            </div>
            <div className="flex items-center justify-between rounded-lg border border-error/40 bg-error/5 p-3">
              <div>
                <p className="text-sm font-bold text-error">{t('settings.resetAll')}</p>
                <p className="text-xs text-text-muted">{t('settings.resetDescription')}</p>
              </div>
              <Button variant="danger" size="sm" onClick={resetAll}>
                <RotateCcw size={14} /> {t('settings.resetButton')}
              </Button>
            </div>
          </div>
        </Card>

        {/* About */}
        <Card padding="lg">
          <h2 className="mb-2 text-lg font-bold text-text-primary">{t('settings.about')}</h2>
          <p className="text-sm text-text-secondary">
            {t('settings.version')}
          </p>
          <p className="mt-2 text-xs text-text-muted">
            {t('settings.credits')}
          </p>
        </Card>
      </div>
    </div>
  );
}